-- phuket: checked place by place on 2026-10-25 (still open, own websites, prices with sources).

UPDATE "Place" p SET "website" = 'https://www.banyantree.com/thailand/phuket' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'banyan-tree-phuket';
UPDATE "Place" p SET "website" = 'https://phuket.intercontinental.com/' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'intercontinental-phuket-resort';
UPDATE "Place" p SET "website" = 'https://lubd.com/' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'lub-d-phuket-patong';
UPDATE "Place" p SET "website" = 'https://www.theblankethotels.com/' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'the-blanket-hotel-phuket-town';
UPDATE "Place" p SET "area" = 'Thalang (between Nai Thon and Bang Tao)', "tip" = 'The old hilltop path is closed; use the parking at the north end (฿100).' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'banana-beach-phuket';
UPDATE "Place" p SET "tip" = 'Tours run every hour from 2 to 6 pm.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'chalong-bay-rum-distillery';
UPDATE "Place" p SET "tip" = 'Boats can''t land on the rock itself; you see it from the water or from Khao Phing Kan beach.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'james-bond-island';
UPDATE "Place" p SET "tip" = 'No alcohol is sold in the village.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'koh-panyi';
UPDATE "Place" p SET "website" = 'https://www.theslatephuket.com/dining/black-ginger.html' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'black-ginger-phuket';
UPDATE "Place" p SET "website" = 'https://www.amari.com/phuket/dine/la-gritta' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'la-gritta';
UPDATE "Place" p SET "name" = 'Lock Tien', "tip" = 'Moved in 2025 from the old Yaowarat and Dibuk corner food court to 59/14 Bangkok Road; now a single restaurant.' FROM "Destination" d WHERE d.id = p."destinationId" AND d.slug = 'phuket' AND p.slug = 'lock-tien';
